        }

        System.out.println();
    }

    public static int calculateFibonacciRecursive(int number) {
        if (number <= 1) {
            return number;
        }

        return calculateFibonacciRecursive(number - 1) + calculateFibonacciRecursive(number - 2);
    }

    public static int calculateSumIterative(int number) {
        if (number <= 0) {
            return 0;
        }

        int sum = 0;
        int first = 0;
        int second = 1;
        int fibonacci;

        sum += first + second;

        for (int i = 2; i < number; i++) {
            fibonacci = first + second;
            sum += fibonacci;
            first = second;
            second = fibonacci;
        }

        return sum;
    }

    public static double calculateAverageIterative(int number) {
        if (number <= 0) {
            return 0;
        }

        int sum = calculateSumIterative(number);
        return (double) sum / number;
    }

    public static long calculateProductIterative(int number) {
        if (number <= 0) {
            return 0;
        }

        long product = 1;
        int first = 0;
        int second = 1;
        int fibonacci;

        product *= first;
        product *= second;

        for (int i = 2; i < number; i++) {
            fibonacci = first + second;
            product *= fibonacci;
            first = second;
            second = fibonacci;
        }

        return product;
    }

    public static void calculateFactorialIterative(int number) {
        for (int i = 0; i < number; i++) {
            System.out.println(i + ": " + calculateFactorialRecursive(calculateFibonacciRecursive(i)));
        }
