        }
    }

    public static boolean isFibonacciNumber(int number) {
        int a = 0;
        int b = 1;
        int fibonacci = a + b;

        while (fibonacci <= number) {
            if (fibonacci == number) {
                return true;
            }
            a = b;
            b = fibonacci;
            fibonacci = a + b;
        }

        return false;
    }
}
