    if rect1[0] + rect1[2] <= rect2[0] or rect1[0] >= rect2[0] + rect2[2] or rect1[1] + rect1[3] <= rect2[1] or rect1[1] >= rect2[1] + rect2[3]:
        return 0
    x1 = max(rect1[0], rect2[0])
    y1 = max(rect1[1], rect2[1])
    x2 = min(rect1[0] + rect1[2], rect2[0] + rect2[2])
    y2 = min(rect1[1] + rect1[3], rect2[1] + rect2[3])

    return (x2 - x1) * (y2 - y1)

