from hashlib import sha256, sha512
import time

class AuthToken:
    def __init__(self, secret, hashfunc=sha256, random_len=64):
        if not isinstance(secret, (str, bytes)):
            raise ValueError("Secret must be a string or bytes")
        if not callable(hashfunc):
            raise ValueError("hashfunc must be a valid hash function")
        if not isinstance(random_len, int) or random_len < 1:
            raise ValueError("random_len must be a positive integer")

        self.secret = secret
        self.hashfunc = hashfunc
        self.random_len = random_len

    def create(self, *metadata):
        for data in metadata:
            if not all(c in string.printable for c in str(data)):
                raise ValueError("Invalid metadata")

        timestamp = str(int(time.time()))
        random_data = os.urandom(self.random_len).hex()
        signature = self.hashfunc((self.secret + timestamp + random_data).encode()).hexdigest()
        return ':'.join([str(m) for m in [timestamp, random_data, signature] + list(metadata)])

    def verify(self, token, time_range=None):
        parts = token.split(':')
        if len(parts) < 3:
            raise ValueError("Invalid token format")

        timestamp, random_data, signature = parts[:3]
        if time_range:
            if int(time.time()) - int(timestamp) > time_range:
                raise ValueError("Token has expired")

        if signature != self.hashfunc((self.secret + timestamp + random_data).encode()).hexdigest():
            raise ValueError("Invalid token signature")

        return tuple(parts[3:])

