Then, create a file named `monitor-directory.js` and add the following code:

```javascript
const fs = require('fs');
const path = require('path');
const zlib = require('zlib');
const AWS = require('aws-sdk');
const chokidar = require('chokidar');

// Configure AWS credentials
AWS.config.update({
  accessKeyId: 'your_access_key_id',
  secretAccessKey: 'your_secret_access_key',
  region: 'your_region'
});

const s3 = new AWS.S3();
const directoryPath = './watched_directory';
const bucketName = 'your_bucket_name';

function uploadFileToS3(filePath) {
  const fileName = path.basename(filePath);
  const gzippedFileName = `${fileName}.gz`;

  // Compress the file using gzip
  const gzip = zlib.createGzip();
  const inputStream = fs.createReadStream(filePath);
  const outputStream = fs.createWriteStream(gzippedFileName);

  inputStream.pipe(gzip).pipe(outputStream).on('finish', () => {
    // Upload the gzipped file to S3
    const fileStream = fs.createReadStream(gzippedFileName);
    const params = {
      Bucket: bucketName,
      Key: gzippedFileName,
      Body: fileStream,
      ContentType: 'application/gzip'
    };

    s3.upload(params, (err, data) => {
      if (err) {
        console.error(`Error uploading ${gzippedFileName} to S3:`, err);
      } else {
        console.log(`Successfully uploaded ${gzippedFileName} to S3:`, data.Location);
        // Delete the gzipped file after uploading
        fs.unlinkSync(gzippedFileName);
      }
    });
  });
}

// Watch for changes in the specified directory
const watcher = chokidar.watch(directoryPath, {
  persistent: true,
  ignoreInitial: true
});

watcher.on('add', (filePath) => {
  console.log(`File added: ${filePath}`);
  uploadFileToS3(filePath);
});
```

Replace `'your_access_key_id'`, `'your_secret_access_key'`, `'your_region'`, `'./watched_directory'`, and `'your_bucket_name'` with your AWS credentials, the path of the directory you want to monitor, and the name of your S3 bucket.

